def word_wrap(text, width):
    if width <= 0:
        raise ValueError("width must be positive")
    if not text:
        return []
    words = text.split()
    if not words:
        return []
    lines = []
    current = ""
    for word in words:
        if len(word) > width:
            if current:
                lines.append(current)
                current = ""
            lines.append(word)
            continue
        if not current:
            current = word
        elif len(current) + 1 + len(word) <= width:
            current += " " + word
        else:
            lines.append(current)
            current = word
    if current:
        lines.append(current)
    return lines
```

